import{_ as h,C as c,o,c as p,a9 as r,b as n,w as t,a as s,E as a,a8 as d,j as u}from"./chunks/framework.BOiBTRPC.js";const D=JSON.parse('{"title":"Architecture & Execution Model","description":"Driver, executors, slots, cluster managers, jobs→stages→tasks, narrow vs wide dependencies, shuffle files, the unified memory model, and DataSource V2.","frontmatter":{"title":"Architecture & Execution Model","description":"Driver, executors, slots, cluster managers, jobs→stages→tasks, narrow vs wide dependencies, shuffle files, the unified memory model, and DataSource V2."},"headers":[],"relativePath":"spark/architecture.md","filePath":"spark/architecture.md"}'),m={name:"spark/architecture.md"};function g(f,e,b,y,k,w){const i=c("Mermaid"),l=c("QuizCard");return o(),p("div",null,[e[7]||(e[7]=r('<h1 id="architecture-execution-model" tabindex="-1">Architecture &amp; Execution Model <a class="header-anchor" href="#architecture-execution-model" aria-label="Permalink to &quot;Architecture &amp; Execution Model&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Every Spark performance problem is an architecture problem in disguise: a shuffle that shouldn&#39;t exist, a straggler task holding 90% of the data, or an executor OOMing because execution memory starved. You can&#39;t tune what you can&#39;t diagram.</p></blockquote><h2 id="the-runtime-driver-executors-slots" tabindex="-1">The runtime: driver, executors, slots <a class="header-anchor" href="#the-runtime-driver-executors-slots" aria-label="Permalink to &quot;The runtime: driver, executors, slots&quot;">​</a></h2><p>A Spark application is <strong>one driver</strong> coordinating <strong>N executors</strong>. The driver builds the plan, schedules tasks, and tracks metadata. Executors run tasks in JVM threads (task slots) and hold cached data.</p>',4)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20APP%5B%22Spark%20Application%22%5D%0A%20%20%20%20D%5B%22Driver%3Cbr%2F%3ESparkSession%20%C2%B7%20DAGScheduler%3Cbr%2F%3ETaskScheduler%20%C2%B7%20plan%20%2B%20schedule%22%5D%0A%20%20%20%20subgraph%20EX1%5B%22Executor%201%22%5D%0A%20%20%20%20%20%20S1%5B%22Task%20slot%22%5D%0A%20%20%20%20%20%20S2%5B%22Task%20slot%22%5D%0A%20%20%20%20%20%20M1%5B%22Memory%3A%20execution%20%2B%20storage%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20EX2%5B%22Executor%202%22%5D%0A%20%20%20%20%20%20S3%5B%22Task%20slot%22%5D%0A%20%20%20%20%20%20S4%5B%22Task%20slot%22%5D%0A%20%20%20%20%20%20M2%5B%22Memory%3A%20execution%20%2B%20storage%22%5D%0A%20%20%20%20end%0A%20%20%20%20D%20%3C--%3E%7C%22launch%20tasks%20%2F%20heartbeats%22%7C%20EX1%0A%20%20%20%20D%20%3C--%3E%7C%22launch%20tasks%20%2F%20heartbeats%22%7C%20EX2%0A%20%20end%0A%20%20CM%5B%22Cluster%20Manager%3Cbr%2F%3EYARN%20%C2%B7%20Kubernetes%20%C2%B7%20Standalone%22%5D%0A%20%20CM%20%3C--%3E%7C%22allocate%20%2F%20release%20containers%22%7C%20APP%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=r('<ul><li><strong>Driver</strong> — owns the <code>SparkSession</code>. Turns your code into a DAG, splits it into stages, negotiates resources. Also collects results (<code>collect</code>, <code>toPandas</code>). If the driver dies, the application dies.</li><li><strong>Executor</strong> — a JVM process on a worker node. Runs tasks, caches blocks, writes shuffle output. Lives for the application&#39;s duration (or is reclaimed under dynamic allocation).</li><li><strong>Task slot</strong> — one executor core runs one task at a time. <code>executor.instances × executor.cores</code> = total parallelism ceiling. 10 executors × 4 cores = 40 concurrent tasks.</li><li><strong>Shuffle service</strong> — an external service (enabled via <code>spark.shuffle.service.enabled</code>) that serves shuffle files so executors can be freed between stages. Required for dynamic allocation.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Driver OOM</p><p><code>collect()</code>, <code>toPandas()</code>, and broadcast variables land on the <strong>driver&#39;s</strong> heap. Pulling 50 GB into <code>collect()</code> doesn&#39;t distribute — it crashes the one machine that can&#39;t be retried. Use <code>collectAsList</code> equivalents or write to storage.</p></div><h2 id="cluster-managers" tabindex="-1">Cluster managers <a class="header-anchor" href="#cluster-managers" aria-label="Permalink to &quot;Cluster managers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Manager</th><th>How it allocates</th><th>When you see it</th></tr></thead><tbody><tr><td><strong>Standalone</strong></td><td>Spark&#39;s built-in; static worker pool</td><td>Small on-prem clusters, dev</td></tr><tr><td><strong>YARN</strong></td><td>Hadoop resource manager; <code>client</code>/<code>cluster</code> deploy modes</td><td>Legacy Hadoop shops, EMR default</td></tr><tr><td><strong>Kubernetes</strong></td><td>Executor pods; driver pod or <code>spark-submit</code> client</td><td>Modern standard; Databricks, EMR on EKS, most self-managed 2024+</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ client vs cluster deploy mode (YARN / K8s)</p><p><code>client</code> mode runs the driver in your submit process (fine for notebooks, dies when you close the laptop). <code>cluster</code> mode runs the driver inside the cluster — required for production and anything that must survive a disconnect.</p></div><h3 id="yarn-vs-kubernetes-—-ops-trade-offs" tabindex="-1">YARN vs Kubernetes — ops trade-offs <a class="header-anchor" href="#yarn-vs-kubernetes-—-ops-trade-offs" aria-label="Permalink to &quot;YARN vs Kubernetes — ops trade-offs&quot;">​</a></h3><p>The 2018 edition of <em>Spark: The Definitive Guide</em> lists only Standalone, Mesos, and YARN — <strong>Spark on Kubernetes postdates it</strong> (experimental in 2.3, GA in Spark 3.1). Current picture:</p><table tabindex="0"><thead><tr><th></th><th>YARN</th><th>Kubernetes</th></tr></thead><tbody><tr><td>Maturity</td><td>Decade+ of production; battle-tested resource queues</td><td>GA since Spark 3.1; now the common green-field default</td></tr><tr><td>Multi-tenancy / queueing</td><td>Strong — Capacity/Fair schedulers, hierarchical queues</td><td>Weaker natively — namespace quotas; add Volcano/YuniKorn for batch queueing</td></tr><tr><td>Resource shape</td><td>Fixed container sizes (memory × vcores)</td><td>Arbitrary pod shapes; sidecars; node affinity per pod</td></tr><tr><td>Elasticity</td><td>Dynamic allocation via external shuffle service</td><td>Dynamic allocation works, but pod teardown needs the shuffle service too — shuffle files live in pods</td></tr><tr><td>Image/deps</td><td>Deps shipped via <code>--jars</code>/<code>--files</code> per job</td><td>Bake Spark + deps into an image; reproducible, versioned</td></tr><tr><td>Ops burden</td><td>Piggybacks on existing Hadoop ops</td><td>You own the K8s cluster; driver pod = a Kubernetes resource you can <code>kubectl</code></td></tr></tbody></table><p>Rule of thumb: if your org already runs Hadoop/HDFS, YARN is the boring right answer. If you&#39;re cloud-native or on object storage, K8s gives you image-level reproducibility and per-job isolation. Mesos support was removed in Spark 3.2 — treat any Mesos guidance in older books as obsolete.</p><h2 id="from-code-to-tasks-jobs-→-stages-→-tasks" tabindex="-1">From code to tasks: jobs → stages → tasks <a class="header-anchor" href="#from-code-to-tasks-jobs-→-stages-→-tasks" aria-label="Permalink to &quot;From code to tasks: jobs → stages → tasks&quot;">​</a></h2><p>An <strong>action</strong> (<code>count</code>, <code>write</code>, <code>collect</code>) triggers a <strong>job</strong>. The DAGScheduler splits the job&#39;s DAG into <strong>stages</strong> at every shuffle boundary. Each stage is a set of <strong>tasks</strong> — one per partition of the final RDD in that stage.</p>',11)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-198",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20J%5B%22Job%20%E2%80%94%20triggered%20by%20df.count%20or%20write%22%5D%0A%20%20%20%20subgraph%20S0%5B%22Stage%200%20%E2%80%94%20narrow%22%5D%0A%20%20%20%20%20%20T1%5B%22Task%20%C2%B7%20partition%201%22%5D%20--%3E%20T2%5B%22Task%20%C2%B7%20partition%202%22%5D%20--%3E%20T3%5B%22Task%20%C2%B7%20partition%203%22%5D%0A%20%20%20%20end%0A%20%20%20%20SH%7B%7B%22SHUFFLE%3Cbr%2F%3Eexchange%20by%20key%22%7D%7D%0A%20%20%20%20subgraph%20S1%5B%22Stage%201%20%E2%80%94%20narrow%20until%20next%20shuffle%20or%20end%22%5D%0A%20%20%20%20%20%20T4%5B%22Task%20%C2%B7%20reducer%201%22%5D%0A%20%20%20%20%20%20T5%5B%22Task%20%C2%B7%20reducer%202%22%5D%0A%20%20%20%20%20%20T6%5B%22Task%20%C2%B7%20reducer%203%22%5D%0A%20%20%20%20end%0A%20%20%20%20S0%20--%3E%20SH%20--%3E%20S1%0A%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=r('<p>Key rules:</p><ul><li><strong>Transformations are lazy</strong> — <code>filter</code>, <code>join</code>, <code>groupBy</code> build a DAG; nothing runs until an action.</li><li><strong>Stages are sequential</strong> — stage N+1 cannot start until every task in stage N finished writing its shuffle output.</li><li><strong>Tasks are the unit of failure and retry</strong> — a straggler re-runs as a <em>speculative</em> or retried task; a stage with one giant partition = one giant task = the classic skew symptom.</li></ul><h3 id="whole-stage-code-generation-—-where-it-fits" tabindex="-1">Whole-stage code generation — where it fits <a class="header-anchor" href="#whole-stage-code-generation-—-where-it-fits" aria-label="Permalink to &quot;Whole-stage code generation — where it fits&quot;">​</a></h3><p>Catalyst&#39;s optimizer produces a physical plan of operators (scan → filter → project → aggregate). Under the hood, <strong>Tungsten&#39;s whole-stage codegen</strong> then compiles each chain of operators <em>between shuffle boundaries</em> into a single Java method — the &quot;volcano&quot; iterator model&#39;s virtual-call overhead disappears, and generated code operates directly on the compact binary row format (below) instead of JVM objects.</p>',4)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-225",class:"mermaid",graph:"flowchart%20LR%0A%20%20SQ%5B%22DataFrame%20%2F%20SQL%22%5D%20--%3E%20LP%5B%22Logical%20plan%22%5D%0A%20%20LP%20--%3E%20PP%5B%22Physical%20plan%3Cbr%2F%3Eoperator%20tree%22%5D%0A%20%20PP%20--%3E%20WS%5B%22Whole-stage%20codegen%3Cbr%2F%3Efused%20Java%20method%20per%20stage%22%5D%0A%20%20WS%20--%3E%20EX%5B%22Tasks%20execute%3Cbr%2F%3Egenerated%20bytecode%20on%20binary%20rows%22%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=r('<p>In the Spark UI&#39;s SQL tab, a <code>WholeStageCodegen</code> box = one fused unit. Operators that can&#39;t fuse — exchanges, some Python UDFs, certain scan paths — split the codegen regions. Practical read: a stage showing several small <code>WholeStageCodegen</code> blocks instead of one big one usually means a non-fusible operator (or your UDF) is breaking the pipeline.</p><p><em>(Version-dependent: codegen is on by default via <code>spark.sql.codegen.wholeStage</code>; in Spark 3.x, AQE can re-optimize plans at stage boundaries but codegen still applies per re-planned stage.)</em></p><h3 id="api-levels-—-what-actually-plans-the-work" tabindex="-1">API levels — what actually plans the work <a class="header-anchor" href="#api-levels-—-what-actually-plans-the-work" aria-label="Permalink to &quot;API levels — what actually plans the work&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>Optimization</th><th>When you use it</th></tr></thead><tbody><tr><td><strong>RDD</strong> (<code>sc.parallelize</code>, <code>.map</code>, <code>.reduceByKey</code>)</td><td>None — you write the physical ops</td><td>Rare today; debugging, custom partitioning, legacy code</td></tr><tr><td><strong>DataFrame / Dataset</strong></td><td>Full Catalyst + codegen</td><td>The default; everything below is free</td></tr><tr><td><strong>Spark SQL</strong></td><td>Same Catalyst engine</td><td>Same plan as DataFrame — interchangeable</td></tr></tbody></table><ul><li><strong>Structured APIs (DataFrame / Dataset / SQL)</strong> — you declare <em>what</em> you want; Catalyst picks the physical plan. Optimizations compound: every release ships improvements you get for free.</li><li><strong>RDDs (low-level)</strong> — you write the physical operators yourself; Spark executes exactly that, no optimization pass.</li></ul><p>The DataFrame API and SQL compile to the <em>same</em> logical plan — <code>df.filter(...).groupBy(...)</code> and the equivalent <code>spark.sql(...)</code> produce identical physical plans. Choosing between them is style, not performance. RDDs bypass Catalyst entirely: no pushdown, no codegen, no AQE. That&#39;s why &quot;rewrite the RDD job as DataFrames&quot; is a legitimate optimization — and why &quot;our custom RDD pipeline is faster&quot; claims deserve skepticism: Catalyst writes better RDD code than almost anyone writes by hand, at a fraction of the effort.</p><h3 id="structured-vs-low-level-the-decision" tabindex="-1">Structured vs low-level: the decision <a class="header-anchor" href="#structured-vs-low-level-the-decision" aria-label="Permalink to &quot;Structured vs low-level: the decision&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Reach for...</th><th>When</th><th>Why</th></tr></thead><tbody><tr><td><strong>DataFrame / SQL</strong></td><td>Default — ~95% of work</td><td>Catalyst optimization, codegen, pushdown, AQE, consistent across languages</td></tr><tr><td><strong>Dataset (Scala/Java)</strong></td><td>Type safety required, or business logic that won&#39;t fit expressions</td><td>Compile-time type checks, encoder converts <code>Row</code> ↔ case class</td></tr><tr><td><strong>RDD</strong></td><td>Custom partitioning control, <code>mapPartitions</code>/<code>pipe</code>, truly unstructured data</td><td>Fine-grained physical control you can&#39;t express declaratively</td></tr><tr><td><strong>RDD from Python</strong></td><td>Almost never</td><td>Python↔JVM serialization on every record — slowest, least stable option</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight (Chambers &amp; Zaharia)</p><p>The book&#39;s canonical RDD use case is <em>fine-grained control over physical data distribution</em> — custom partitioning, <code>repartitionAndSortWithinPartitions</code>, per-partition work. If you&#39;re on an RDD because &quot;the DataFrame version is slow,&quot; the answer is almost always fixing the SQL plan, not abandoning it. And if you must use RDDs, use them from Scala/Java: Python RDDs serialize data in and out of the Python process for every transformation.</p></div><h3 id="the-serialization-tax-why-python-udfs-cost" tabindex="-1">The serialization tax: why Python UDFs cost <a class="header-anchor" href="#the-serialization-tax-why-python-udfs-cost" aria-label="Permalink to &quot;The serialization tax: why Python UDFs cost&quot;">​</a></h3><p>A Python UDF isn&#39;t &quot;Python running your function on a row.&quot; The full path per executor:</p>',11)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-375",class:"mermaid",graph:"flowchart%20LR%0A%20%20JVM%5B%22JVM%20task%3Cbr%2F%3ETungsten%20binary%20rows%22%5D%20--%3E%7C%22serialize%20batch%3Cbr%2F%3Eto%20Python%20format%22%7C%20PY%5B%22Python%20worker%3Cbr%2F%3Erow-by-row%20UDF%22%5D%0A%20%20PY%20--%3E%7C%22serialize%20results%3Cbr%2F%3Eback%20to%20JVM%22%7C%20OUT%5B%22JVM%20task%20continues%22%5D%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[s(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=r('<p>Three separate costs stack:</p><ol><li><strong>Process startup</strong> — Spark forks a Python worker on the executor (one per task slot). Real but amortizable.</li><li><strong>Serialization both ways</strong> — data must be converted out of Spark&#39;s internal binary format into a format Python can read, then results converted back. This is the dominant cost and it scales with data volume.</li><li><strong>Unmanaged memory</strong> — once data enters the Python process, Spark can no longer account for or bound it. JVM and Python workers compete for the same RAM; Python-side blowups show as container kills, not JVM OOMs.</li></ol><p>Mitigations, in preference order: use built-in <code>functions.*</code> (JVM-native, codegen-eligible); write the UDF in Scala/Java and call it from Python (book&#39;s recommendation — you keep PySpark ergonomics without the per-row crossing); use a <strong>pandas/Arrow UDF</strong> (<code>pandas_udf</code>), which vectorizes the crossing via Apache Arrow batches — the serialization cost becomes per-<em>batch</em>, not per-row, and Arrow&#39;s columnar format is near-zero-copy. <em>(Version-dependent: pandas UDFs exist since Spark 2.3; Arrow integration improves through 3.x — postdates the 2018 book.)</em></p><h3 id="dataset-vs-untyped-what-typed-apis-buy" tabindex="-1">Dataset vs untyped: what typed APIs buy <a class="header-anchor" href="#dataset-vs-untyped-what-typed-apis-buy" aria-label="Permalink to &quot;Dataset vs untyped: what typed APIs buy&quot;">​</a></h3><p><code>DataFrame</code> <em>is</em> <code>Dataset[Row]</code> — &quot;Dataset&quot; as an API means the <strong>typed</strong> variant, JVM-only (Scala/Java). An <strong>Encoder</strong> maps your case class / JavaBean to Spark&#39;s internal binary row format at runtime.</p><table tabindex="0"><thead><tr><th></th><th>DataFrame (<code>Dataset[Row]</code>)</th><th>Typed <code>Dataset[T]</code></th></tr></thead><tbody><tr><td>Type errors surface at</td><td>Runtime</td><td>Compile time</td></tr><tr><td>Per-row cost</td><td>Stays in binary row format</td><td>Encoder converts <code>Row</code> → object → back, every row touched</td></tr><tr><td>Languages</td><td>Scala, Java, Python, R</td><td>Scala, Java only</td></tr><tr><td>Best for</td><td>Everything by default</td><td>Reused Scala-library transformations; correctness-critical boundaries</td></tr></tbody></table><p>The encoder conversion is real overhead — the book flags it as the Dataset tax — but it&#39;s JVM-internal, so it&#39;s an order of magnitude cheaper than a Python UDF. Common pattern: <strong>DataFrames for the ETL body, Datasets at the boundaries</strong> (per-row parsing in, typed collection out to the driver).</p><p><code>SparkSession</code> wraps the older <code>SparkContext</code>/<code>SQLContext</code> — a session is the entry point; <code>spark.sparkContext</code> still exists underneath for RDD ops, accumulators, and broadcast variables.</p><h2 id="narrow-vs-wide-dependencies" tabindex="-1">Narrow vs wide dependencies <a class="header-anchor" href="#narrow-vs-wide-dependencies" aria-label="Permalink to &quot;Narrow vs wide dependencies&quot;">​</a></h2>',9)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-475",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20N%5B%22Narrow%20%E2%80%94%20each%20parent%20partition%20feeds%20%E2%89%A41%20child%22%5D%0A%20%20%20%20A1%5B%22P1%22%5D%20--%3E%20B1%5B%22P1'%22%5D%0A%20%20%20%20A2%5B%22P2%22%5D%20--%3E%20B2%5B%22P2'%22%5D%0A%20%20%20%20A3%5B%22P3%22%5D%20--%3E%20B3%5B%22P3'%22%5D%0A%20%20end%0A%20%20subgraph%20W%5B%22Wide%20%E2%80%94%20children%20need%20data%20from%20many%20parents%22%5D%0A%20%20%20%20C1%5B%22P1%22%5D%20--%3E%20D1%5B%22P1'%22%5D%0A%20%20%20%20C2%5B%22P2%22%5D%20--%3E%20D1%0A%20%20%20%20C3%5B%22P3%22%5D%20--%3E%20D1%0A%20%20%20%20C1%20--%3E%20D2%5B%22P2'%22%5D%0A%20%20%20%20C2%20--%3E%20D2%0A%20%20%20%20C3%20--%3E%20D2%0A%20%20end%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[s(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=r('<table tabindex="0"><thead><tr><th></th><th>Narrow</th><th>Wide</th></tr></thead><tbody><tr><td>Examples</td><td><code>map</code>, <code>filter</code>, <code>union</code> (same partitioner), <code>mapValues</code></td><td><code>groupByKey</code>, <code>reduceByKey</code>, <code>join</code> (un-partitioned), <code>distinct</code>, <code>sortBy</code></td></tr><tr><td>Shuffle</td><td>No</td><td><strong>Yes</strong> — new stage boundary</td></tr><tr><td>Fault recovery</td><td>Recompute one partition</td><td>Recompute + re-shuffle (expensive)</td></tr><tr><td>Pipelining</td><td>Fuse into one task</td><td>Blocks pipelining</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p><code>reduceByKey</code> is narrow in cost but wide in mechanics — it shuffles, <em>but</em> it pre-aggregates on the map side first. <code>groupByKey</code> shuffles every record unreduced. Never write <code>groupByKey</code> when a <code>reduceByKey</code>/<code>aggregateByKey</code>/<code>agg</code> expresses the same thing — it&#39;s the single most common avoidable shuffle blowup.</p></div><h3 id="fault-tolerance-lineage-not-replication" tabindex="-1">Fault tolerance: lineage, not replication <a class="header-anchor" href="#fault-tolerance-lineage-not-replication" aria-label="Permalink to &quot;Fault tolerance: lineage, not replication&quot;">​</a></h3><p>RDDs recover by <strong>recomputing lost partitions from the lineage</strong> (the recorded transformation DAG), not by replicating data. Narrow losses recompute one partition cheaply; a lost partition feeding a wide dependency may force a whole ancestor stage to re-run — which is why long lineages get <code>checkpoint()</code>ed (see <a href="/Data-Knowledge/spark/optimization.html">Optimization</a>).</p><p>Two practical consequences:</p><ul><li><strong>Speculative execution</strong> (<code>spark.speculation=true</code>) re-runs tasks that are slower than the stage median on a second executor and keeps whichever finishes first — helps stragglers, harmless for skew.</li><li><strong><code>spark.task.maxFailures</code></strong> (default 4) bounds per-task retries; repeated task failure at the <em>same</em> partition usually means bad data at a specific input offset, not a flaky executor.</li></ul><details class="details custom-block"><summary>Why no replication? The cost model</summary><p>Replicating every intermediate RDD across nodes would double memory and add network cost for data that&#39;s usually recomputable from raw inputs in seconds. Spark bets that lineage + retained shuffle files beat replication for batch analytics. The bet breaks for very long, branching DAGs (iterative ML, graph) — that&#39;s exactly where <code>checkpoint()</code> exists.</p></details><h2 id="what-a-shuffle-actually-writes" tabindex="-1">What a shuffle actually writes <a class="header-anchor" href="#what-a-shuffle-actually-writes" aria-label="Permalink to &quot;What a shuffle actually writes&quot;">​</a></h2><p>When a stage finishes, each map task sorts its output by target partition and writes <strong>one data file plus one index file</strong> (the sort-based shuffle, default since Spark 2.0). The index records each partition&#39;s offset range inside the data file, so each reducer fetches only its slice from every map output — via the external shuffle service or local disk.</p><p>Consequences that matter in production:</p><ul><li>Shuffle files are <strong>on local disk</strong> — executor loss or spot-preemption forces recomputation unless the shuffle service retained them.</li><li><code>spark.sql.shuffle.partitions</code> (default <strong>200</strong>) sets the reduce-side partition count for SQL shuffles — the #1 knob for &quot;too many tiny tasks&quot; or &quot;too few giant tasks&quot; before AQE existed.</li><li>Spill during shuffle writes disk pressure; the external shuffle service decouples read availability from executor lifetime.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ The 200 partition default</p><p>A 2 GB shuffle with <code>shuffle.partitions=200</code> = ~10 MB partitions and 200 mostly-empty tasks. A 2 TB shuffle = ~10 GB partitions and tasks that OOM. The default is wrong at both ends — AQE&#39;s coalescing fixes the small side automatically, but you still own the large side.</p></div><h3 id="why-shuffles-dominate-cost" tabindex="-1">Why shuffles dominate cost <a class="header-anchor" href="#why-shuffles-dominate-cost" aria-label="Permalink to &quot;Why shuffles dominate cost&quot;">​</a></h3><p>A shuffle is three expensive things at once:</p><ul><li><strong>Serialization</strong> — every record leaves the JVM object world, gets serialized, and is deserialized on the far side.</li><li><strong>Network + disk</strong> — full data movement across nodes, written to local disk on the map side and read back over the network by reducers. No shuffle ever ran in memory end-to-end.</li><li><strong>A barrier</strong> — the next stage can&#39;t start until <em>every</em> map task finished; the slowest map task sets the floor.</li></ul><p>This is why &quot;reduce shuffle volume&quot; (pre-aggregate, broadcast, prune before the exchange) beats almost every other optimization: you&#39;re attacking serialization, network, and the stage barrier simultaneously.</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Fetch failure = the cascade</p><p><code>FetchFailedException</code> — a reducer can&#39;t read a map&#39;s shuffle output (executor died, disk full, shuffle service down) — triggers a <strong>stage retry</strong>: the whole map stage recomputes. Chronic fetch failures usually mean executors are being killed (spot, OOM) or disk is saturated, not a code bug.</p></div><h2 id="the-unified-memory-model" tabindex="-1">The unified memory model <a class="header-anchor" href="#the-unified-memory-model" aria-label="Permalink to &quot;The unified memory model&quot;">​</a></h2><p>Executor JVM heap is split (since Spark 1.6, refined through 3.x):</p>',19)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-636",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20H%5B%22Executor%20memory%22%5D%0A%20%20%20%20subgraph%20UM%5B%22Unified%20region%20%E2%80%94%20spark.memory.fraction%2C%20default%200.6%22%5D%0A%20%20%20%20%20%20EX%5B%22Execution%20memory%3Cbr%2F%3Eshuffles%20%C2%B7%20joins%20%C2%B7%20sorts%20%C2%B7%20aggregations%22%5D%0A%20%20%20%20%20%20ST%5B%22Storage%20memory%3Cbr%2F%3Ecached%20RDD%2FDataFrame%20blocks%22%5D%0A%20%20%20%20end%0A%20%20%20%20O%5B%22Reserved%20%2B%20user%20memory%20~0.4%3Cbr%2F%3Eyour%20objects%2C%20UDF%20data%22%5D%0A%20%20end%0A%20%20EX%20%3C-.-%3E%7C%22borrow%20when%20free%22%7C%20ST%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[s(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=r('<ul><li><strong>Execution memory</strong> — transient buffers for shuffles, joins, sorts, aggregations. <strong>Can evict storage</strong> when needed.</li><li><strong>Storage memory</strong> — cached/persisted blocks. Can borrow execution space but <strong>cannot evict execution</strong>.</li><li><strong>Spill</strong> — when execution memory fills, Spark sorts and writes intermediate data to local disk and reads it back. Spill is normal; <em>spilling every task</em> means under-provisioned memory or skew.</li></ul><h3 id="tungsten-binary-rows-vs-jvm-objects" tabindex="-1">Tungsten binary rows vs JVM objects <a class="header-anchor" href="#tungsten-binary-rows-vs-jvm-objects" aria-label="Permalink to &quot;Tungsten binary rows vs JVM objects&quot;">​</a></h3><p>Structured-API data inside the JVM isn&#39;t Java objects — it&#39;s Tungsten&#39;s <strong>internal binary row format</strong>: fixed-width fields packed directly, variable-length fields as offset+data, managed as off-heap (<code>sun.misc.Unsafe</code>) or serialized-on-heap memory. This is why DataFrames beat both RDDs of case classes and naive expectations.</p><table tabindex="0"><thead><tr><th></th><th>Tungsten binary row</th><th>JVM object (RDD of case classes, Python <code>Row</code>)</th></tr></thead><tbody><tr><td>Memory per row</td><td>~bytes of actual fields + small header</td><td>Object header + field pointers + padding — often 2–5× the logical size</td></tr><tr><td>GC pressure</td><td>Minimal (few large managed regions)</td><td>Every row = a live object → GC churn at scale</td></tr><tr><td>Cache locality</td><td>Contiguous, cache-line friendly</td><td>Pointer-chasing across the heap</td></tr><tr><td>SerDe at shuffle</td><td>Already serialized — writes nearly verbatim</td><td>Full Java/Kryo serialization round-trip</td></tr><tr><td>Who manages it</td><td>Spark (bounded, spillable)</td><td>JVM heap — your OOM problem</td></tr></tbody></table><p>This is the mechanical reason behind the earlier rules: Python UDFs are expensive because data must <em>leave</em> this format; encoders cost because they convert it to objects; and <code>cache()</code> on a DataFrame stores compact binary blocks while <code>rdd.cache()</code> stores bloated objects. <em>(Book context: Tungsten shipped in 1.4–1.6; Chambers &amp; Zaharia describe the binary format without naming it — the name comes from the Databricks project that built it.)</em></p><table tabindex="0"><thead><tr><th>Symptom in UI</th><th>Cause</th></tr></thead><tbody><tr><td>High <code>Spill (Memory)</code></td><td>Tasks needed more execution memory than share — check skew or raise <code>executor.memory</code></td></tr><tr><td>Tasks OOM, <code>Storage memory</code> near zero</td><td>Cache evicted everything; drop unnecessary <code>persist</code> or raise <code>memory.storageFraction</code></td></tr><tr><td>GC time &gt; ~10% of task time</td><td>Memory pressure — objects churning; consider Kryo or fewer/larger partitions</td></tr></tbody></table><h2 id="datasource-v2" tabindex="-1">DataSource V2 <a class="header-anchor" href="#datasource-v2" aria-label="Permalink to &quot;DataSource V2&quot;">​</a></h2><p>DSv2 is the modern connector API (default since Spark 3 for most built-ins). It exists because DSv1 couldn&#39;t express predicate/filter pushdown, column pruning, or report partitioning cleanly.</p><ul><li>Enables <strong>pushdown</strong> of filters and projections into the scan (read less).</li><li>Supports <strong>partition-aware</strong> reads and writes — the table&#39;s partitioning is visible to the planner.</li><li>Table formats (Iceberg, Delta, Hudi) plug in via DSv2 catalogs; <code>spark.sql.catalog.*</code> registers them.</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️ Why you care</p><p>A DSv1 source may silently ignore <code>df.filter(...)</code> in the scan and read everything. Check <code>explain</code> for <code>PushedFilters</code> — if they&#39;re absent, your &quot;cheap filter&quot; reads the whole table.</p></div><h2 id="the-config-that-actually-matters" tabindex="-1">The config that actually matters <a class="header-anchor" href="#the-config-that-actually-matters" aria-label="Permalink to &quot;The config that actually matters&quot;">​</a></h2><p>Most of <code>spark-defaults.conf</code> is noise. These move the needle:</p><table tabindex="0"><thead><tr><th>Config</th><th>Default</th><th>Why</th></tr></thead><tbody><tr><td><code>spark.executor.memory</code> / <code>.cores</code> / <code>.instances</code></td><td>—</td><td>Sizing. Roughly: enough memory for shuffle partitions + cache, cores 4–5/executor for GC balance</td></tr><tr><td><code>spark.sql.shuffle.partitions</code></td><td>200</td><td>Reduce-side task count; tune per data size</td></tr><tr><td><code>spark.sql.adaptive.enabled</code></td><td>true (3.2+)</td><td>AQE — leave on</td></tr><tr><td><code>spark.dynamicAllocation.enabled</code></td><td>false</td><td>Scale executors with load; needs shuffle service</td></tr><tr><td><code>spark.serializer</code></td><td>Java</td><td>Set <code>KryoSerializer</code> for perf</td></tr><tr><td><code>spark.sql.files.maxPartitionBytes</code></td><td>128 MB</td><td>Read-side partition size for file scans</td></tr><tr><td><code>spark.memory.fraction</code> / <code>.storageFraction</code></td><td>0.6 / 0.5</td><td>Unified-memory split; rarely tune, know it exists</td></tr></tbody></table><h3 id="executor-sizing-rules-of-thumb" tabindex="-1">Executor sizing rules of thumb <a class="header-anchor" href="#executor-sizing-rules-of-thumb" aria-label="Permalink to &quot;Executor sizing rules of thumb&quot;">​</a></h3><ul><li><strong>Fat vs thin executors:</strong> many 1-core executors waste JVM overhead; one giant executor concentrates risk and GC pauses. Sweet spot: <strong>4–6 cores, 16–32 GB</strong> per executor.</li><li><code>executor.memory</code> ≈ (shuffle buffers + cached data + overhead). Spark adds <code>spark.executor.memoryOverhead</code> (~10% or 384 MB min) on top for off-heap/Python — on K8s the pod requests the sum; under-budget it and the pod gets OOM-killed, not the task.</li><li><strong>PySpark adds a Python worker per task slot</strong> — Python data lives <em>outside</em> the JVM heap (in <code>memoryOverhead</code>), so PySpark OOMs often show as container kills, not Java OOMs.</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️ SparkSession is the one config surface</p><p><code>SparkSession.builder.config(...)</code> (or <code>spark-defaults.conf</code>, <code>spark-submit --conf</code>) sets everything above. Runtime-tunable <code>spark.sql.*</code> keys can also be set per-session with <code>spark.conf.set</code> — useful for <code>shuffle.partitions</code> before a specific heavy join.</p></div><h2 id="where-structured-streaming-fits" tabindex="-1">Where structured streaming fits <a class="header-anchor" href="#where-structured-streaming-fits" aria-label="Permalink to &quot;Where structured streaming fits&quot;">​</a></h2><p>Structured Streaming is not a separate engine — it&#39;s <strong>the same Catalyst/Tungsten engine run in micro-batches</strong>. The driver plans a sequence of incremental executions over an unbounded table; each trigger fires a normal Spark job. Continuous processing exists but is deprecated-in-practice; micro-batch (and its <em>available-now</em> trigger) is the model that matters.</p>',18)),(o(),n(d,null,{default:t(()=>[a(i,{id:"mermaid-932",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%5B%22Source%3Cbr%2F%3EKafka%20%C2%B7%20files%20%C2%B7%20Pulsar%22%5D%20--%3E%20MB%5B%22Micro-batch%20engine%3Cbr%2F%3ECatalyst%20plan%20per%20trigger%22%5D%0A%20%20MB%20--%3E%20CK%5B%22Checkpoint%20%2F%20state%20store%3Cbr%2F%3Eprogress%20%2B%20state%22%5D%0A%20%20MB%20--%3E%20SINK%5B%22Sink%22%5D%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[s(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=u("h2",{id:"🧠-quiz",tabindex:"-1"},[s("🧠 Quiz "),u("a",{class:"header-anchor",href:"#🧠-quiz","aria-label":'Permalink to "🧠 Quiz"'},"​")],-1)),a(l,{questions:[{q:"A job has 4 stages; stage 2 shows 199 tasks done in seconds and one task running 40 minutes. What is the most likely cause?",options:["Broadcast join failure","Data skew — one shuffle partition holds a hot key","Driver out of memory","Too few executors"],correct:1,explain:"A single long tail task inside one stage is the canonical skew signature — the data hashed to one reduce partition dominates all others."},{q:"Which transformation creates a stage boundary?",options:["map","union of identically partitioned inputs","groupByKey","filter"],correct:2,explain:"groupByKey requires a shuffle (wide dependency). filter/map are narrow and fuse; a union over same-partitioned inputs stays narrow."},{q:"In the unified memory model, which is true?",options:["They are fixed, non-overlapping pools","Storage memory can evict execution memory","Execution memory can evict storage memory","Spill writes cached blocks to S3"],correct:2,explain:"Execution memory (shuffles/joins) takes precedence and can borrow/evict storage; storage cannot evict execution. Spill goes to local disk."},{q:"What does spark.sql.shuffle.partitions control?",options:["Read-side file split size","Broadcast threshold","Number of partitions after a shuffle in SQL/DataFrame ops","Executor thread count"],correct:2,explain:"It sets reduce-side partition count for shuffles. Read-side splits are spark.sql.files.maxPartitionBytes."},{q:"Why prefer cluster deploy mode for production?",options:["The driver runs inside the cluster and survives client disconnects","It is faster","It enables AQE","It disables the shuffle service"],correct:0,explain:"In client mode the driver lives in your submit process — close the laptop, lose the job. Cluster mode keeps the driver with the executors."},{q:"A cached DataFrame keeps getting evicted and recomputed. What is happening?",options:["GC is too slow","The shuffle service is down","Kryo is not registered","Execution memory is evicting storage blocks under shuffle pressure"],correct:3,explain:"Execution memory has priority — heavy shuffle/join pressure can evict cached blocks, forcing recompute on next use."}]}),a(l,{questions:[{q:"A PySpark job is 10x slower than the equivalent Scala job, and the executor logs show heavy serialization between JVM and a Python process. What is the dominant fix?",options:["Switch to cluster deploy mode","Enable Kryo serialization","Increase executor memory","Replace the row-by-row Python UDF with built-in functions, a Scala UDF, or a pandas Arrow UDF"],correct:3,explain:"Every record must be serialized out of the JVM binary row format into Python and back. Built-in functions stay in codegen; Arrow batching turns the per-row crossing into a per-batch one."},{q:"Why does a Spark UI stage show a WholeStageCodegen box?",options:["The stage failed and was retried","The data is stored as JVM objects","Catalyst fused the operator chain between shuffle boundaries into one generated Java method","The stage was compiled by AQE"],correct:2,explain:"Whole-stage codegen compiles all fusible operators in a stage into a single method operating on compact binary rows, eliminating per-operator virtual-call overhead. Non-fusible ops split it into multiple boxes."},{q:"Your org is cloud-native on object storage and wants per-job dependency isolation and reproducible images. Which cluster manager fits?",options:["Kubernetes","Mesos","YARN","Standalone"],correct:0,explain:"K8s lets you bake Spark plus dependencies into a versioned image per job. YARN fits Hadoop shops; Mesos support was removed in Spark 3.2."}]}),e[15]||(e[15]=r('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://spark.apache.org/docs/latest/cluster-overview.html" target="_blank" rel="noreferrer">Spark Cluster Mode Overview — official docs</a></li><li><a href="https://spark.apache.org/docs/latest/configuration.html" target="_blank" rel="noreferrer">Spark Configuration — official docs</a></li><li><a href="https://spark.apache.org/docs/latest/sql-performance-tuning.html" target="_blank" rel="noreferrer">Spark SQL Performance Tuning — official docs</a></li><li><a href="https://www.databricks.com/blog/2015/04/28/project-tungsten-bringing-spark-closer-to-bare-metal.html" target="_blank" rel="noreferrer">Project Tungsten: Bringing Spark Closer to Bare Metal — Databricks</a></li><li><a href="https://japila.pl/apache-spark-internals/" target="_blank" rel="noreferrer">Apache Spark Internals — Jacek Laskowski</a></li><li><em>Spark: The Definitive Guide</em> — Bill Chambers &amp; Matei Zaharia (2018), <a href="https://www.oreilly.com/library/view/spark-the-definitive/9781491912201/" target="_blank" rel="noreferrer">O&#39;Reilly</a></li><li><em>Learning Spark, 2nd Edition</em> — Damji, Wenig, Das, Lee (O&#39;Reilly) — <a href="https://pages.databricks.com/rs/094-YMS-629/images/LearningSpark2.0.pdf" target="_blank" rel="noreferrer">free PDF from Databricks</a></li></ul>',2))])}const S=h(m,[["render",g]]);export{D as __pageData,S as default};
